{
  "existing": [
    {
      "candidate_name": "ATTEMPTS_TO_REPAIR",
      "matched_existing_name": "ATTEMPTS_TO_REPAIR"
    }
  ],
  "new": [
    {
      "name": "INVESTIGATES_FAILURE_CAUSE",
      "definition": "A subsequent diagnostic action gathers information about the cause or environment of an earlier observed failure or blocker.",
      "source_description": "An earlier observed execution failure, error, or blocker.",
      "target_description": "A subsequent diagnostic action that inspects system state, constraints, or capabilities relevant to the failure."
    },
    {
      "name": "OBSERVATION_GUIDES_SUBSEQUENT_ACTION",
      "definition": "An observation about the task environment, available resources, or input data is used by the agent to select or parameterize a subsequent action.",
      "source_description": "An execution observation providing relevant environmental, resource, or data-state information.",
      "target_description": "A subsequent agent action or decision shaped by that observation."
    },
    {
      "name": "DIAGNOSTIC_RESULT_GUIDES_REPAIR",
      "definition": "A diagnostic observation revealing an environmental constraint or incompatibility directs the choice of a specific corrective action.",
      "source_description": "A diagnostic observation that identifies a constraint, incompatibility, or capability gap.",
      "target_description": "A subsequent repair action selected to satisfy or work around that diagnostic finding."
    },
    {
      "name": "SUCCESSFUL_SETUP_ENABLES_SUBSEQUENT_USE",
      "definition": "A successful installation or environment setup action makes a capability available that the agent subsequently uses.",
      "source_description": "A successful setup or installation action result.",
      "target_description": "A subsequent action that relies on the installed or configured capability."
    }
  ],
  "uncertain": [
    {
      "name": "VERIFIES_OUTCOME_OF_PREVIOUS_ACTION",
      "definition": "A subsequent agent action checks the completion status, result, or side effect of an earlier action.",
      "source_description": "An earlier agent action whose outcome is uncertain, asynchronous, or needs confirmation.",
      "target_description": "A subsequent check or inspection that determines whether the earlier action completed or produced the expected result."
    }
  ]
}

